"use client";

import * as React from "react";
import {
  MotionConfig,
  useInView as useMotionInView,
  type Transition,
} from "motion/react";
import { useHydratedReducedMotion } from "@/lib/use-reduced-motion";
import { cn } from "@/lib/utils";

const TempoContext = React.createContext(1);

export function PrequelMotionProvider({
  tempo = 1,
  children,
}: {
  tempo?: number;
  children: React.ReactNode;
}) {
  const value = React.useMemo(() => Math.max(0.4, tempo), [tempo]);
  return (
    <TempoContext.Provider value={value}>
      <MotionConfig reducedMotion="user">{children}</MotionConfig>
    </TempoContext.Provider>
  );
}

export function useTempo() {
  return React.useContext(TempoContext);
}

const TIME_KEYS = [
  "duration",
  "visualDuration",
  "delay",
  "repeatDelay",
  "delayChildren",
] as const;

function scaleValue(transition: Transition, tempo: number): Transition {
  if (tempo === 1 || !transition || typeof transition !== "object") {
    return transition;
  }
  const next: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(transition)) {
    if (typeof value === "number" && (TIME_KEYS as readonly string[]).includes(key)) {
      next[key] = value * tempo;
    } else if (typeof value === "number" && key === "stiffness") {
      next[key] = value / (tempo * tempo);
    } else if (typeof value === "number" && key === "damping") {
      next[key] = value / tempo;
    } else if (value && typeof value === "object" && !Array.isArray(value)) {
      next[key] = scaleValue(value as Transition, tempo);
    } else {
      next[key] = value;
    }
  }
  return next as Transition;
}

export function useTempoTransition(transition: Transition) {
  const tempo = useTempo();
  return React.useMemo(
    () => scaleValue(transition, tempo),
    [tempo, JSON.stringify(transition)],
  );
}

export function useReduceMotion() {
  return useHydratedReducedMotion();
}

export function usePageVisible() {
  const [visible, setVisible] = React.useState(true);
  React.useEffect(() => {
    const update = () => setVisible(!document.hidden);
    update();
    document.addEventListener("visibilitychange", update);
    return () => document.removeEventListener("visibilitychange", update);
  }, []);
  return visible;
}

export function useMounted() {
  return React.useSyncExternalStore(
    () => () => {},
    () => true,
    () => false,
  );
}

export function useSeen(
  ref: React.RefObject<Element | null>,
  enabled = true,
  once = true,
) {
  const inView = useMotionInView(ref, { once, amount: 0.35 });
  return enabled ? inView : true;
}

type SlotProps = React.HTMLAttributes<HTMLElement> & {
  children?: React.ReactNode;
  ref?: React.Ref<HTMLElement>;
};

export function Slot({ children, ...props }: SlotProps) {
  if (!React.isValidElement<Record<string, unknown>>(children)) {
    return null;
  }
  const child = children as React.ReactElement<Record<string, unknown>>;
  const childProps = child.props;
  return React.cloneElement(child, {
    ...props,
    ...childProps,
    className: cn(
      String(props.className ?? ""),
      String(childProps.className ?? ""),
    ),
    style: {
      ...((props.style as React.CSSProperties) ?? {}),
      ...((childProps.style as React.CSSProperties) ?? {}),
    },
  } as Record<string, unknown>);
}

export function srOnlyStyle(): React.CSSProperties {
  return {
    position: "absolute",
    width: 1,
    height: 1,
    padding: 0,
    margin: -1,
    overflow: "hidden",
    clip: "rect(0, 0, 0, 0)",
    whiteSpace: "nowrap",
    borderWidth: 0,
  };
}

let segmenter: Intl.Segmenter | null | undefined;

export function splitGraphemes(text: string): string[] {
  if (segmenter === undefined) {
    segmenter =
      typeof Intl !== "undefined" && typeof Intl.Segmenter === "function"
        ? new Intl.Segmenter(undefined, { granularity: "grapheme" })
        : null;
  }
  if (!segmenter) return Array.from(text);
  return Array.from(segmenter.segment(text), (entry) => entry.segment);
}

export const easeOut = [0.23, 1, 0.32, 1] as const;
export const easeSoft = [0.215, 0.61, 0.355, 1] as const;
export const easeInOut = [0.77, 0, 0.175, 1] as const;
export const easeEnter = [0.25, 0.1, 0.35, 1] as const;
export const easeLeave = [0, 0, 0.58, 1] as const;
export const easeResize = [0.4, 0, 0.1, 1] as const;
export const easeAway = [0.33, 0.17, 0.67, 0.5] as const;

export const pressSpring: Transition = {
  type: "spring",
  stiffness: 550,
  damping: 30,
  restSpeed: 10,
};

export const selectionSpring: Transition = {
  type: "spring",
  stiffness: 300,
  damping: 30,
};

export const highlightSpring: Transition = {
  type: "spring",
  stiffness: 500,
  damping: 40,
};

export const popSpring: Transition = {
  type: "spring",
  stiffness: 400,
  damping: 29,
};

export const tooltipSpring: Transition = {
  type: "spring",
  stiffness: 400,
  damping: 31,
};

export const dialogSpring: Transition = {
  type: "spring",
  stiffness: 150,
  damping: 25,
};

export const toastSpring: Transition = {
  type: "spring",
  stiffness: 280,
  damping: 24,
};

export const heightSpring: Transition = {
  type: "spring",
  stiffness: 300,
  damping: 30,
  bounce: 0,
  restDelta: 0.01,
};

export const progressSpring: Transition = {
  type: "spring",
  stiffness: 300,
  damping: 35,
  restDelta: 0.01,
  restSpeed: 0.1,
};

export const scrollSpring: Transition = {
  type: "spring",
  stiffness: 250,
  damping: 40,
  bounce: 0,
};

export const avatarSpring: Transition = {
  type: "spring",
  stiffness: 300,
  damping: 17,
};

export const pinnedSpring: Transition = {
  type: "spring",
  stiffness: 320,
  damping: 25,
  mass: 0.8,
};

export const thumbSpring: Transition = {
  type: "spring",
  stiffness: 300,
  damping: 25,
};

export const checkSpring: Transition = {
  type: "spring",
  stiffness: 500,
  damping: 24,
};

export const cursorEntry: Transition = {
  type: "spring",
  stiffness: 550,
  damping: 30,
  restSpeed: 10,
};

export const cursorExit: Transition = {
  type: "spring",
  stiffness: 550,
  damping: 46.9,
  restSpeed: 10,
};

export const cursorLabel: Transition = {
  type: "spring",
  stiffness: 500,
  damping: 50,
  bounce: 0,
};

export const swapTween: Transition = {
  duration: 0.15,
  ease: easeOut,
};

export const overlayTween: Transition = {
  duration: 0.4,
  ease: easeSoft,
};

export const disclosureTween: Transition = {
  duration: 0.35,
  ease: easeSoft,
};

export const menuTween: Transition = {
  duration: 0.22,
  ease: easeSoft,
};

export const panelOutTween: Transition = {
  duration: 0.15,
  ease: easeLeave,
};

export const panelInTween: Transition = {
  duration: 0.3,
  ease: easeEnter,
};

export const panelHeightTween: Transition = {
  duration: 0.45,
  ease: easeResize,
};

export const exitTween: Transition = {
  duration: 0.2,
  ease: easeAway,
};

export const faceSpring: Transition = {
  type: "spring",
  stiffness: 280,
  damping: 20,
};

export const blurIcon = "blur(2px)";

export function flipTransform(side: "top" | "bottom" | "left" | "right") {
  const rotate =
    side === "top"
      ? "rotateX(-20deg)"
      : side === "bottom"
        ? "rotateX(20deg)"
        : side === "left"
          ? "rotateY(20deg)"
          : "rotateY(-20deg)";
  return `perspective(500px) ${rotate} scale(0.8)`;
}

export function uprightTransform(side: "top" | "bottom" | "left" | "right") {
  const rotate = side === "left" || side === "right" ? "rotateY(0deg)" : "rotateX(0deg)";
  return `perspective(500px) ${rotate} scale(1)`;
}

"use client";

import { useReducedMotion } from "motion/react";
import { useSyncExternalStore } from "react";

const subscribe = () => () => {};

export function useHydratedReducedMotion() {
  const reduce = useReducedMotion() ?? false;
  const mounted = useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  );
  return mounted ? reduce : false;
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function slugToTitle(slug: string) {
  return slug
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

export function formatDate(date: Date) {
  return new Intl.DateTimeFormat("en-US", {
    month: "2-digit",
    day: "2-digit",
    year: "numeric",
  }).format(date);
}

"use client";

import * as React from "react";
import {
  useAnimationControls,
  useInView,
  type TargetAndTransition,
  type Transition,
  type Variants,
} from "motion/react";
import { Slot, useReduceMotion, useTempo } from "../motion";
import {
  IconStyleProvider,
  type IconVariant,
  type IconWeight,
} from "./style";

export type IconAnimationSet = Record<string, Record<string, Variants>>;
export type IconTrigger = boolean | string;
export type IconControls = ReturnType<typeof useAnimationControls>;

type IconContextValue = {
  controls: IconControls;
  animation: string;
  speed: number;
};

const IconContext = React.createContext<IconContextValue | null>(null);

export function useAnimatedIconContext() {
  return React.useContext(IconContext);
}

const TIME_KEYS = new Set([
  "duration",
  "delay",
  "repeatDelay",
  "delayChildren",
  "staggerChildren",
]);

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function scaleTransition(transition: Transition, factor: number): Transition {
  if (factor === 1) return transition;
  const next: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(transition)) {
    if (typeof value === "number" && TIME_KEYS.has(key)) next[key] = value * factor;
    else if (typeof value === "number" && key === "stiffness")
      next[key] = value / (factor * factor);
    else if (typeof value === "number" && key === "damping") next[key] = value / factor;
    else if (isPlainObject(value)) next[key] = scaleTransition(value as Transition, factor);
    else next[key] = value;
  }
  return next as Transition;
}

function scaleTarget(
  target: TargetAndTransition,
  factor: number,
): TargetAndTransition {
  if (!isPlainObject(target)) return target;
  const next: Record<string, unknown> = { ...target };
  if (isPlainObject(next.transition)) {
    next.transition = scaleTransition(next.transition as Transition, factor);
  }
  return next as TargetAndTransition;
}

function scalePart(part: Variants, factor: number): Variants {
  if (factor === 1) return part;
  const next: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(part)) {
    if (key === "transition" && isPlainObject(value)) {
      next[key] = scaleTransition(value as Transition, factor);
    } else {
      next[key] = scaleTarget(value as TargetAndTransition, factor);
    }
  }
  return next as Variants;
}

export function useIconVariants(animations: IconAnimationSet): Record<string, Variants> {
  const context = React.useContext(IconContext);
  const tempo = useTempo();
  const animation = context?.animation ?? "default";
  const speed = context?.speed ?? 1;
  const factor = tempo / Math.max(0.05, speed);
  const set =
    animations[animation] ??
    animations.default ??
    animations.hover ??
    Object.values(animations)[0] ??
    {};

  return React.useMemo(() => {
    if (factor === 1) return set;
    const next: Record<string, Variants> = {};
    for (const [part, variants] of Object.entries(set)) {
      next[part] = scalePart(variants, factor);
    }
    return next;
  }, [factor, set]);
}

export type AnimatedIconProps = Omit<React.ComponentProps<"span">, "children"> & {
  children: React.ReactNode;
  animate?: IconTrigger;
  animateOnHover?: IconTrigger;
  animateOnTap?: IconTrigger;
  animateOnView?: IconTrigger;
  animateOnViewOnce?: boolean;
  animateOnViewMargin?: string;
  animation?: string;
  loop?: boolean;
  loopDelay?: number;
  delay?: number;
  speed?: number;
  variant?: IconVariant;
  weight?: IconWeight;
  asChild?: boolean;
};

export function AnimatedIcon({
  children,
  animate = false,
  animateOnHover = false,
  animateOnTap = false,
  animateOnView = false,
  animateOnViewOnce = true,
  animateOnViewMargin = "0px",
  animation = "default",
  loop = false,
  loopDelay = 0,
  delay = 0,
  speed = 1,
  variant,
  weight,
  asChild = false,
  className,
  onPointerEnter,
  onPointerLeave,
  onPointerDown,
  onPointerUp,
  onPointerCancel,
  ...props
}: AnimatedIconProps) {
  const controls = useAnimationControls();
  const reduce = useReduceMotion();
  const ref = React.useRef<HTMLSpanElement>(null);
  const [active, setActive] = React.useState(false);
  const [currentAnimation, setCurrentAnimation] = React.useState(animation);
  const pending = React.useRef<number | undefined>(undefined);
  const [mounted, setMounted] = React.useState(false);
  const alive = React.useRef(true);

  React.useEffect(() => setMounted(true), []);

  /* The animation effects clean up passively, after paint. A frame scheduled
     just before an unmount could therefore still reach the controls after
     motion has detached them. The layout cleanup runs synchronously, so the
     callbacks below can bail out before touching a dead controller. */
  React.useLayoutEffect(() => {
    alive.current = true;
    return () => {
      alive.current = false;
    };
  }, []);

  const inView = useInView(ref, {
    once: animateOnViewOnce,
    amount: 0.5,
    margin: animateOnViewMargin as `${number}px`,
  });

  const clearPending = React.useCallback(() => {
    if (pending.current !== undefined) {
      window.clearTimeout(pending.current);
      pending.current = undefined;
    }
  }, []);

  const start = React.useCallback(
    (trigger: IconTrigger) => {
      if (!trigger || reduce) return;
      clearPending();
      const next = typeof trigger === "string" ? trigger : animation;
      setCurrentAnimation(next);
      if (delay > 0) {
        pending.current = window.setTimeout(() => setActive(true), delay);
      } else {
        setActive(true);
      }
    },
    [animation, clearPending, delay, reduce],
  );

  const stop = React.useCallback(() => {
    clearPending();
    setActive(false);
  }, [clearPending]);

  React.useEffect(() => {
    if (animate) start(animate);
    else stop();
  }, [animate, start, stop]);

  React.useEffect(() => {
    setCurrentAnimation(typeof animate === "string" ? animate : animation);
  }, [animate, animation]);

  React.useEffect(() => {
    if (!animateOnView) return;
    if (inView) start(animateOnView);
    else stop();
  }, [animateOnView, inView, start, stop]);

  React.useEffect(() => {
    if (!mounted) return;

    let cancelled = false;
    let frame = 0;
    let timer: number | undefined;

    const run = async () => {
      if (cancelled || !alive.current) return;
      await controls.start("animate");
      if (cancelled || !alive.current) return;
      if (loop) {
        timer = window.setTimeout(run, Math.max(0, loopDelay));
      } else {
        setActive(false);
      }
    };

    frame = window.requestAnimationFrame(() => {
      if (cancelled || !alive.current) return;
      if (!active || reduce) {
        void controls.start("initial");
        return;
      }
      void run();
    });

    return () => {
      cancelled = true;
      window.cancelAnimationFrame(frame);
      if (timer !== undefined) window.clearTimeout(timer);
    };
  }, [active, controls, currentAnimation, loop, loopDelay, mounted, reduce]);

  React.useEffect(() => {
    return () => {
      if (pending.current !== undefined) window.clearTimeout(pending.current);
    };
  }, []);

  const Component = (asChild ? Slot : "span") as React.ElementType;

  return (
    <IconContext.Provider
      value={{ controls, animation: currentAnimation, speed }}
    >
      <IconStyleProvider variant={variant} weight={weight}>
        <Component
          ref={ref}
          data-slot="animated-icon"
          className={className}
          onPointerEnter={(event: React.PointerEvent<HTMLElement>) => {
            onPointerEnter?.(event as React.PointerEvent<HTMLSpanElement>);
            if (animateOnHover && event.pointerType !== "touch") start(animateOnHover);
          }}
          onPointerLeave={(event: React.PointerEvent<HTMLElement>) => {
            onPointerLeave?.(event as React.PointerEvent<HTMLSpanElement>);
            if (animateOnHover || animateOnTap) stop();
          }}
          onPointerDown={(event: React.PointerEvent<HTMLElement>) => {
            onPointerDown?.(event as React.PointerEvent<HTMLSpanElement>);
            if (animateOnTap) start(animateOnTap);
          }}
          onPointerUp={(event: React.PointerEvent<HTMLElement>) => {
            onPointerUp?.(event as React.PointerEvent<HTMLSpanElement>);
            if (animateOnTap) stop();
          }}
          onPointerCancel={(event: React.PointerEvent<HTMLElement>) => {
            onPointerCancel?.(event as React.PointerEvent<HTMLSpanElement>);
            if (animateOnTap) stop();
          }}
          {...props}
        >
          {children}
        </Component>
      </IconStyleProvider>
    </IconContext.Provider>
  );
}

export type AnimatedSvgProps = React.ComponentProps<"svg"> & {
  size?: number;
  children: React.ReactNode;
};

"use client";

import * as React from "react";
import type { IconVariant, IconWeight, IconRole } from "@/lib/icon-styles";

export type { IconVariant, IconWeight, IconRole } from "@/lib/icon-styles";
export {
  ICON_VARIANTS,
  ICON_VARIANT_LABELS,
  ICON_VARIANT_SUFFIX,
  isIconVariant,
} from "@/lib/icon-styles";

export type IconPalette = {
  primary: string;
  primaryDark: string;
  accent: string;
  accentDark: string;
};

export type IconEmojiPalette = {
  primary: string;
  secondary: string;
  accent: string;
};

export type IconPaletteBundle = {
  color: IconPalette;
  emoji: IconEmojiPalette;
};

type IconPaintStyle = React.CSSProperties;

export type IconPaintApi = {
  variant: IconVariant;
  weight: IconWeight;
  part: (
    role: IconRole,
    closed: boolean,
    draw?: boolean,
    inside?: boolean,
  ) => IconPaintStyle;
  halo: (role: IconRole) => IconPaintStyle;
  flash: () => IconPaintStyle;
  sticker: () => IconPaintStyle;
  highlight: () => IconPaintStyle;
};

type IconStyleContextValue = {
  variant?: IconVariant;
  weight?: IconWeight;
};

const IconStyleContext = React.createContext<IconStyleContextValue>({});

export function IconStyleProvider({
  variant,
  weight,
  children,
}: {
  variant?: IconVariant;
  weight?: IconWeight;
  children: React.ReactNode;
}) {
  const value = React.useMemo(() => ({ variant, weight }), [variant, weight]);
  return (
    <IconStyleContext.Provider value={value}>{children}</IconStyleContext.Provider>
  );
}

export function useIconStyle() {
  return React.useContext(IconStyleContext);
}

function lightDark(light: string, dark: string) {
  return `light-dark(${light}, ${dark})`;
}

const INK = "light-dark(oklch(0.28 0.02 80 / 0.7), oklch(0.92 0.02 80 / 0.55))";

const OUTLINE_WIDTH: Record<IconWeight, number> = {
  light: 1.75,
  regular: 2,
  bold: 2.6,
};

const SOLID_WIDTH: Record<IconWeight, number> = {
  light: 2.4,
  regular: 2.8,
  bold: 3.2,
};

const EMOJI_WIDTH: Record<IconWeight, number> = {
  light: 2.3,
  regular: 2.6,
  bold: 3,
};

export function useIconPaint(
  palette?: IconPaletteBundle,
  localVariant?: IconVariant,
  localWeight?: IconWeight,
): IconPaintApi {
  const context = React.useContext(IconStyleContext);
  const variant = context.variant ?? localVariant ?? "outline";
  const weight = context.weight ?? localWeight ?? "regular";

  return React.useMemo(() => {
    const stroke = OUTLINE_WIDTH[weight];
    const solidOpen = SOLID_WIDTH[weight];
    const emojiStroke = EMOJI_WIDTH[weight];

    const primary = palette
      ? lightDark(palette.color.primary, palette.color.primaryDark)
      : "currentColor";
    const accent = palette
      ? lightDark(palette.color.accent, palette.color.accentDark)
      : "currentColor";
    const tint = `color-mix(in oklab, ${primary} var(--pi-tint, 22%), transparent)`;
    const emoji = palette?.emoji;
    const emojiPrimary = emoji?.primary ?? "currentColor";
    const emojiSecondary = emoji?.secondary ?? "currentColor";
    const emojiAccent = emoji?.accent ?? "currentColor";

    function part(
      role: IconRole,
      closed: boolean,
      draw = false,
      isInside = false,
    ): IconPaintStyle {
      if (variant === "solid") {
        if (isInside) {
          const cutout =
            "var(--pi-cutout, light-dark(oklch(1 0 0), oklch(0.145 0 0)))";
          return closed
            ? { fill: cutout, stroke: cutout, strokeWidth: draw ? stroke : 1 }
            : { fill: "none", stroke: cutout, strokeWidth: stroke };
        }
        if (closed) {
          return {
            fill: "currentColor",
            fillRule: "evenodd",
            stroke: "currentColor",
            strokeWidth: draw ? stroke : 1,
          };
        }
        return { fill: "none", stroke: "currentColor", strokeWidth: solidOpen };
      }

      if (variant === "duotone") {
        if (closed) {
          return {
            fill: "currentColor",
            fillOpacity: "var(--pi-secondary, 0.2)",
            fillRule: "evenodd",
            stroke: "currentColor",
            strokeWidth: stroke,
          };
        }
        return { fill: "none", stroke: "currentColor", strokeWidth: stroke };
      }

      if (variant === "color") {
        const tone = role === "accent" ? accent : primary;
        return {
          fill: closed ? tint : "none",
          fillRule: "evenodd",
          stroke: tone,
          strokeWidth: stroke,
        };
      }

      if (variant === "emoji") {
        if (closed) {
          return {
            fill: role === "accent" ? emojiAccent : emojiPrimary,
            fillRule: "evenodd",
            stroke: INK,
            strokeWidth: emojiStroke,
          };
        }
        return {
          fill: "none",
          stroke: role === "accent" ? emojiAccent : emojiPrimary,
          strokeWidth: emojiStroke,
        };
      }

      return { fill: "none", stroke: "currentColor", strokeWidth: stroke };
    }

    function halo(role: IconRole): IconPaintStyle {
      if (variant === "emoji") {
        return {
          fill: "none",
          stroke: INK,
          strokeWidth: emojiStroke + 1.6,
        };
      }
      if (variant === "duotone") {
        return {
          fill: "none",
          stroke: role === "accent" ? accent : primary,
          strokeOpacity: "var(--pi-secondary, 0.2)",
          strokeWidth: stroke + 4,
        };
      }
      return { display: "none" };
    }

    function flash(): IconPaintStyle {
      if (variant === "color") return { fill: primary };
      if (variant === "emoji") return { fill: emojiPrimary };
      if (variant === "duotone") {
        return {
          fill: "currentColor",
          fillOpacity: "var(--pi-secondary, 0.2)",
        };
      }
      return { fill: "currentColor" };
    }

    function sticker(): IconPaintStyle {
      if (!emoji) return { display: "none" };
      return {
        fill: emojiSecondary,
        fillOpacity: 0.26,
        stroke: INK,
        strokeOpacity: 0.22,
        strokeWidth: 1.2,
      };
    }

    function highlight(): IconPaintStyle {
      return {
        fill: "oklch(1 0 0)",
        fillOpacity: "var(--pi-highlight, 0.22)",
        stroke: "none",
      };
    }

    return {
      variant,
      weight,
      part,
      halo,
      flash,
      sticker,
      highlight,
    };
  }, [palette, variant, weight]);
}

export type IconVariant = "outline" | "solid" | "duotone" | "color" | "emoji";
export type IconWeight = "light" | "regular" | "bold";
export type IconRole = "primary" | "secondary" | "accent";

export const ICON_VARIANTS: IconVariant[] = [
  "outline",
  "solid",
  "duotone",
  "color",
  "emoji",
];

export const ICON_VARIANT_LABELS: Record<IconVariant, string> = {
  outline: "Outline",
  solid: "Solid",
  duotone: "Duotone",
  color: "Color",
  emoji: "Emoji",
};

export const ICON_VARIANT_SUFFIX: Record<IconVariant, string> = {
  outline: "",
  solid: "-solid",
  duotone: "-duotone",
  color: "-color",
  emoji: "-emoji",
};

export function isIconVariant(
  value: string | null | undefined,
): value is IconVariant {
  return !!value && (ICON_VARIANTS as string[]).includes(value);
}

